# ═══════════════════════════════════════════════════════════════════════════
# 2. BARÈME DE DÉRIVATION — DÉTERMINISTE
#
#    Trois grandeurs, trois pièges, expliqués une fois pour toutes :
#
#    MW informatiques   la puissance des serveurs. C'est ce que les exploitants
#                       annoncent. Ce n'est PAS la puissance tirée du réseau.
#    PUE                rapport entre l'énergie totale du site et l'énergie
#                       informatique. Un PUE de 1,3 signifie 30 % d'énergie en
#                       plus pour refroidir, onduler, éclairer.
#    Facteur de charge  un site n'a jamais ses serveurs à 100 % en permanence.
#                       Retenir 100 % gonflerait tous les résultats.
#
#    WUE                litres d'eau consommés par kilowattheure informatique.
#                       Il dépend massivement du mode de refroidissement : un
#                       site en free cooling nordique et un site adiabatique
#                       espagnol ne sont pas comparables.
# ═══════════════════════════════════════════════════════════════════════════

HEURES_AN = 8760

# Fourchettes, jamais de valeur unique : la vérité d'un site inconnu est un
# intervalle, et présenter un point donnerait une précision qu'on n'a pas.
CHARGE = (0.55, 0.80)          # facteur de charge annuel moyen

PUE = {                        # (mini, maxi) par mode de refroidissement
    "free_cooling":          (1.10, 1.25),
    "recuperation_chaleur":  (1.10, 1.30),
    "eau":                   (1.15, 1.35),
    "adiabatique":           (1.20, 1.45),
    "air":                   (1.30, 1.60),
    "inconnu":               (1.15, 1.55),
}

WUE = {                        # litres d'eau par kWh informatique
    "free_cooling":          (0.00, 0.10),
    "recuperation_chaleur":  (0.00, 0.20),
    "air":                   (0.00, 0.20),
    "eau":                   (0.20, 1.20),
    "adiabatique":           (0.80, 2.20),
    "inconnu":               (0.00, 2.20),
}

AVERTISSEMENT = (
    "Ces deux grandeurs sont CALCULÉES, jamais mesurées. Lorsqu'un site n'annonce "
    "pas sa capacité — c'est le cas de la quasi-totalité d'entre eux — le calcul "
    "part de l'ordre de grandeur TYPIQUE de sa catégorie et répond alors à « de "
    "quel ordre est un campus de ce type ? », jamais à « combien consomme ce "
    "site ? ». Aucune de ces fourchettes ne peut fonder une comparaison entre "
    "deux sites précis, ni se substituer à une déclaration d'exploitant."
)

FORMULE_ELEC = ("capacité MW × 8 760 h × facteur de charge (%.2f–%.2f) × PUE (%s) "
                "→ GWh par an")
FORMULE_EAU = ("capacité MW × 8 760 h × facteur de charge (%.2f–%.2f) × WUE (%s L/kWh) "
               "→ m³ par an")


def _fourchette_pue(mode):
    return PUE.get(mode, PUE["inconnu"])


def _fourchette_wue(mode):
    return WUE.get(mode, WUE["inconnu"])


def estimer(site):
    """Ordre de grandeur annuel d'électricité (GWh) et d'eau (m³).

    Trois natures possibles, toujours nommées dans le résultat :
      site    la capacité de CE site est annoncée — on en dérive ;
      classe  elle ne l'est pas, on donne l'ordre de grandeur de son GABARIT ;
      indisponible  ni capacité, ni gabarit : on ne dit rien.
    Jamais de valeur unique : la vérité d'un site inconnu est un intervalle."""
    mw = site.get("capacite_mw")
    mode = site.get("refroidissement") or "inconnu"
    if mw:
        mw_min = mw_max = float(mw)
        nature, base_libelle = "site", "capacité annoncée %g MW" % mw
    else:
        g = GABARITS.get(site.get("gabarit"))
        if not g:
            return {"nature": "indisponible", "electricite": None, "eau": None,
                    "formule_electricite": None, "formule_eau": None,
                    "gabarit_nom": None,
                    "motif": "ni capacité annoncée, ni gabarit — aucune dérivation possible"}
        mw_min, mw_max = g["mw"]
        nature = "classe"
        base_libelle = "gabarit « %s » : %g–%g MW informatiques" % (g["nom"], mw_min, mw_max)

    pue_min, pue_max = _fourchette_pue(mode)
    wue_min, wue_max = _fourchette_wue(mode)
    # MWh informatiques bruts, avant PUE
    base_min = mw_min * HEURES_AN * CHARGE[0]
    base_max = mw_max * HEURES_AN * CHARGE[1]

    elec = (round(base_min * pue_min / 1000.0, 1),      # MWh → GWh
            round(base_max * pue_max / 1000.0, 1))
    # 1 kWh informatique × WUE (L/kWh) → litres ; ÷ 1000 → m³
    eau = (round(base_min * 1000 * wue_min / 1000.0),
           round(base_max * 1000 * wue_max / 1000.0))

    return {
        "nature": nature,
        "base": base_libelle,
        "gabarit_nom": (GABARITS.get(site.get("gabarit")) or {}).get("nom"),
        "electricite": list(elec),
        "eau": list(eau),
        "formule_electricite": base_libelle + " × 8 760 h × facteur de charge "
            "(%.2f–%.2f) × PUE (%.2f–%.2f) → GWh par an" % (CHARGE[0], CHARGE[1], pue_min, pue_max),
        "formule_eau": base_libelle + " × 8 760 h × facteur de charge "
            "(%.2f–%.2f) × WUE (%.2f–%.2f L/kWh) → m³ par an" % (CHARGE[0], CHARGE[1], wue_min, wue_max),
        "motif": None,
    }


# ═══════════════════════════════════════════════════════════════════════════
# 2 bis. GABARITS — l'ordre de grandeur QUAND LE SITE NE DIT RIEN
#
#    La verification adversariale a ete severe : sur 97 sites retenus, AUCUN
#    ne conserve de capacite en MW attestee. C'est le resultat honnete d'un
#    marche ou les exploitants annoncent des investissements et des surfaces,
#    presque jamais des megawatts informatiques.
#
#    Laisser la colonne vide partout reviendrait a ne rien dire d'un sujet dont
#    l'ordre de grandeur est justement l'enjeu. On introduit donc un TROISIEME
#    niveau, strictement distinct des deux autres et toujours nomme :
#
#      publie   l'exploitant a publie le chiffre                (aucun ici)
#      site     derive de la capacite ANNONCEE de CE site       (aucun ici)
#      classe   derive du GABARIT TYPIQUE de sa categorie       (le cas courant)
#
#    Un chiffre « classe » repond a « de quel ordre est un campus hyperscale ? »,
#    jamais a « combien consomme CE site ? ». La carte l'ecrit a chaque fois.
# ═══════════════════════════════════════════════════════════════════════════

GABARITS = {
    "hyperscale": {
        "nom": "Campus hyperscale",
        "mw": (30.0, 150.0),
        "sens": "campus en propre d'un fournisseur mondial, livre par tranches sur "
                "plusieurs annees — la fourchette couvre le site jeune et le site mur",
    },
    "campus_ia": {
        "nom": "Campus dédié à l'IA",
        "mw": (100.0, 400.0),
        "sens": "generation annoncee depuis 2024 pour l'entrainement de modeles : "
                "densite par baie sans commune mesure avec le calcul classique",
    },
    "colocation": {
        "nom": "Colocation / opérateur d'hébergement",
        "mw": (5.0, 40.0),
        "sens": "batiment ou petit campus loue a des tiers, monte en charge progressive",
    },
    "regional": {
        "nom": "Site régional ou spécialisé",
        "mw": (1.0, 15.0),
        "sens": "operateur national, centre de calcul public, site industriel dedie",
    },
}

